import{_ as i,C as n,o as s,c as d,a2 as r,E as t,a as o,j as l}from"./chunks/framework.CdvW4CUT.js";const _=JSON.parse('{"title":"Копытко Олег Иванович — резюме","description":"","frontmatter":{},"headers":[],"relativePath":"cv.md","filePath":"cv.md"}'),p={name:"cv.md"};function u(h,a,c,b,f,m){const e=n("Badge");return s(),d("div",null,[a[0]||(a[0]=r('<h1 id="копытко-олег-иванович-—-резюме" tabindex="-1">Копытко Олег Иванович — резюме <a class="header-anchor" href="#копытко-олег-иванович-—-резюме" aria-label="Permalink to &quot;Копытко Олег Иванович — резюме&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">📄 Печатная версия</p><p><strong><a href="./cv.pdf" target="_blank">Скачать резюме в формате PDF</a></strong></p></div><h2 id="стек-и-технологии" tabindex="-1">Стек и технологии <a class="header-anchor" href="#стек-и-технологии" aria-label="Permalink to &quot;Стек и технологии&quot;">​</a></h2>',3)),t(e,{type:"info",text:"Docs-as-Code"}),a[1]||(a[1]=o()),t(e,{type:"info",text:"OpenAPI 3.0"}),a[2]||(a[2]=o()),a[3]||(a[3]=l("br",null,null,-1)),t(e,{type:"tip",text:"Git / CI/CD"}),a[4]||(a[4]=o()),t(e,{type:"tip",text:"VitePress"}),a[5]||(a[5]=o()),a[6]||(a[6]=l("br",null,null,-1)),t(e,{type:"warning",text:"Markdownlint"}),a[7]||(a[7]=r('<h2 id="опыт-работы" tabindex="-1">Опыт работы <a class="header-anchor" href="#опыт-работы" aria-label="Permalink to &quot;Опыт работы&quot;">​</a></h2><h3 id="инженер-по-техническои-документации-ооо-илада-инк-2025-н-в" tabindex="-1">Инженер по технической документации | ООО ИЛАДА ИНК (2025-н.в.) <a class="header-anchor" href="#инженер-по-техническои-документации-ооо-илада-инк-2025-н-в" aria-label="Permalink to &quot;Инженер по технической документации | ООО ИЛАДА ИНК (2025-н.в.)&quot;">​</a></h3><p>С нуля разработал комплект текстовой конструкторской, программной и эксплуатационной документации на линейку радиостанций и ретрансляторов в соответствии с <strong>ЕСКД</strong> и <strong>ЕСПД</strong>. Создал и организовал работу технического архива. Выполнил подготовку полного пакета документации для регистрации ряда программ в реестре Минцифры/РРПО и оборудования в реестре Минпромторга/ГИСП (<code>ПП 719</code>). Перевёл разработку документации на концепцию <code>Doc As Code</code>. Значительно сократил время подготовки документации за счет использования <code>LLM</code>. Дополнительно выполняю нормоконтроль всей выпущенной на предприятии технической документации.</p><h3 id="техническии-писатель-начальник-отдела-техническои-документации-стандартизации-и-нормоконтроля-оао-ниаи-источник-2024-2025" tabindex="-1">Технический писатель/Начальник отдела технической документации, стандартизации и нормоконтроля | ОАО НИАИ Источник (2024-2025) <a class="header-anchor" href="#техническии-писатель-начальник-отдела-техническои-документации-стандартизации-и-нормоконтроля-оао-ниаи-источник-2024-2025" aria-label="Permalink to &quot;Технический писатель/Начальник отдела технической документации, стандартизации и нормоконтроля | ОАО НИАИ Источник (2024-2025)&quot;">​</a></h3><ul><li>В качестве технического писателя: <ol><li>полностью разработал и сопровождал текстовую и графическую КД и ЭД на новую линейку электротехнического и электрохимического оборудования в соответствии с ЕСКД, ЕСПД, ГОСТ РВ;</li><li>принимал участие в разработке различной нормативной и научно-технической документации.</li></ol></li><li>В качества начальника отдела: <ol><li>организация работы архива подлинников КД, ТД и ПД, архива нормативно-технической документации, группы нормоконтроля и группы технических писателей;</li><li>реорганизация структуры и внутренних процессов подразделения для обеспечения эффективного взаимодействия со службами предприятия и представителями Заказчика с целью своевременной защиты технических решений и выполнения стратегических задач.</li></ol></li></ul><h3 id="техническии-писатель-oao-радар-ммс-2023-2024" tabindex="-1">Технический писатель | OAO Радар ММС (2023-2024) <a class="header-anchor" href="#техническии-писатель-oao-радар-ммс-2023-2024" aria-label="Permalink to &quot;Технический писатель | OAO Радар ММС (2023-2024)&quot;">​</a></h3><p>Разработка и сопровождение технической и эксплуатационной документации на электрооборудование и программно-аппаратные комплексы в соответствии с ЕСКД и ЕСПД.</p><h3 id="начальник-отдела-ит-ооо-телис-2018-2023" tabindex="-1">Начальник отдела ИТ | ООО ТЕЛИС (2018-2023) <a class="header-anchor" href="#начальник-отдела-ит-ооо-телис-2018-2023" aria-label="Permalink to &quot;Начальник отдела ИТ | ООО ТЕЛИС (2018-2023)&quot;">​</a></h3><p>Разработка специализированного ПО для нужд операторов фиксированной и мобильной связи, взаимодействие с заказчиками и подрядчиками. Выполнение функций руководителя проектов в проектах по модернизации оборудования и ПО на сетях ПАО &quot;Ростелеком&quot; и ПАО &quot;Мегафон&quot;.</p><h3 id="старшии-преподаватель-фгбоу-во-санкт-петербургскии-государственныи-университет-телекоммуникации-им-проф-м-а-бонч-бруевича-2017-2018" tabindex="-1">Старший преподаватель | ФГБОУ ВО Санкт-Петербургский Государственный Университет Телекоммуникаций им. проф. М.А.Бонч-Бруевича (2017-2018) <a class="header-anchor" href="#старшии-преподаватель-фгбоу-во-санкт-петербургскии-государственныи-университет-телекоммуникации-им-проф-м-а-бонч-бруевича-2017-2018" aria-label="Permalink to &quot;Старший преподаватель | ФГБОУ ВО Санкт-Петербургский Государственный Университет Телекоммуникаций им. проф. М.А.Бонч-Бруевича (2017-2018)&quot;">​</a></h3><p>Разработка учебно-методических материалов, проведение лекций, практических и лабораторных работ по курсам: стандартизация и сертификация в связи; управление качеством; стандартизация, сертификация и управление качеством ПО; экономика программной инженерии; операционные системы.</p><h3 id="начальник-отдела-ит-ооо-элсис-спб-2008-2017" tabindex="-1">Начальник отдела ИТ | ООО ЭЛСИС-СПб (2008-2017) <a class="header-anchor" href="#начальник-отдела-ит-ооо-элсис-спб-2008-2017" aria-label="Permalink to &quot;Начальник отдела ИТ | ООО ЭЛСИС-СПб (2008-2017)&quot;">​</a></h3><p>Техническая и административная работа по договорам поддержки телекоммуникационного оборудования и ПО, разработка оборудования и ПО для диспетчеризации. Выполнение функций администрирования парка ИТ-оборудования компании.</p>',13))])}const x=i(p,[["render",u]]);export{_ as __pageData,x as default};
